function countGoodArrays(n, m, k) {
  const MOD = 1000000007n;
  const power = (base, exponent) => {
    let result = 1n;
    while (exponent > 0n) {
      if (exponent % 2n === 1n) {
        result = result * base % MOD;
      }
      base = base * base % MOD;
      exponent /= 2n;
    }
    return result;
  };
  let top = 1n;
  let bottom = 1n;
  for (let i = 1; i <= k; i++) {
    top = top * BigInt(n - i) % MOD;
    bottom = bottom * BigInt(i) % MOD;
  }
  const choosePairs = top * power(bottom, MOD - 2n) % MOD;
  const changes = power(BigInt(m - 1), BigInt(n - 1 - k));
  return Number(BigInt(m) * changes % MOD * choosePairs % MOD);
}

