function countGoodArrays(n, m, k) {
  // Build the array one element at a time. ways.get(j) counts the prefixes with exactly j equal neighbours;
  // a new element repeats the previous one (1 way, j + 1) or differs from it (m - 1 ways, j stays).
  // Only counts that can still end at exactly k are kept, which keeps the map small when k is near 0 or n - 1.
  const MOD = 1000000007;
  let ways = new Map([[0, m % MOD]]);
  for (let length = 1; length < n; length++) {
    const left = n - 1 - length;
    const next = new Map();
    for (const [j, count] of ways) {
      if (j + 1 <= k && j + 1 + left >= k) next.set(j + 1, ((next.get(j + 1) ?? 0) + count) % MOD);
      if (j + left >= k) next.set(j, ((next.get(j) ?? 0) + count * (m - 1)) % MOD);
    }
    ways = next;
  }
  return ways.get(k) ?? 0;
}

