function generate(rand, size) {
  if (size === 'large') {
    const n = 90000 + Math.floor(rand() * 10001);
    const m = 1 + Math.floor(rand() * 100000);
    return [n, m, Math.floor(rand() * n)];
  }
  const n = 1 + Math.floor(rand() * 12);
  const m = rand() < 0.7 ? 1 + Math.floor(rand() * 5) : 1 + Math.floor(rand() * 100000);
  return [n, m, Math.floor(rand() * n)];
}
